import type { SalesListResponse, VoidError } from './types.js'

// ---------------------------------------------------------------------------
// Sales History API — fetches and voids past sales
//
// Calls the server's GET /api/sales and PATCH /api/sales/:id/void endpoints.
// Uses raw fetch (not apiClient) to match the pattern used by checkout.ts,
// since the server returns plain JSON without an envelope wrapper.
// ---------------------------------------------------------------------------

const API_BASE = ''

// ============================================================================
// Fetch Sales List
// ============================================================================

/**
 * Fetch the sales history list.
 *
 * @param limit — Maximum number of recent sales to return (default: 50)
 * @returns Sales list response with array and total count
 */
export async function fetchSalesList(limit = 50): Promise<SalesListResponse> {
  const response = await fetch(`${API_BASE}/api/sales?limit=${limit}`)

  if (!response.ok) {
    throw new Error(`Failed to fetch sales list: ${response.status}`)
  }

  return (await response.json()) as SalesListResponse

import { Hono } from 'hono'
import { db } from '@/db/index.js'
import { bicycles } from '@/db/schema.js'
import { eq } from 'drizzle-orm'

const bicyclesRoutes = new Hono()

// ---------------------------------------------------------------------------
// GET /api/bicycles/:id — Get a single bicycle by ID (includes isLease flag)
// ===========================================================================

bicyclesRoutes.get('/:id', async (c) => {
  const id = c.req.param('id')

  const [bicycle] = await db.select().from(bicycles).where(eq(bicycles.id, id))
  if (!bicycle) {
    return c.json({ error: 'Bicycle not found', code: 'NOT_FOUND' }, 404)
  }

  return c.json({ bicycle })
})

export default bicyclesRoutes
